//! Toggle/Switch component
//!
//! A toggle switch for boolean values with optional selection highlighting
//! for plugin parameter editing.
//!
//! Features:
//! - Click to toggle state
//! - Space key to toggle when selected
//! - Optional label
//! - Two visual styles: Sliding (iOS-style) and Segmented ([OFF|ON])

// r2factor:facade — do not pass this file back into r2factor
// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use crate::accessibility::{AccessibilityExt, AccessibilityNode, AriaProps, AriaRole, AriaState};
use crate::theme::ThemeExt;
use gpui::prelude::{InteractiveElement, IntoElement, ParentElement, RenderOnce, Styled};
use gpui::{
    App, Div, ElementId, FontWeight, MouseButton, Rgba, SharedString, Stateful, Window, div, px,
};

mod toggle_size;
mod types;

pub use toggle_size::ToggleSize;
pub use types::{ToggleStyle, ToggleTheme};
/// A toggle switch component with optional selection highlighting
pub struct Toggle {
    id: ElementId,
    checked: bool,
    label: Option<SharedString>,
    size: ToggleSize,
    style: ToggleStyle,
    disabled: bool,
    selected: bool,
    theme: Option<ToggleTheme>,
    on_change: Option<Box<dyn Fn(bool, &mut Window, &mut App) + 'static>>,
    aria_label: Option<SharedString>,
    aria_role: Option<AriaRole>,
}

impl Toggle {
    /// Create a new toggle
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            checked: false,
            label: None,
            size: ToggleSize::default(),
            style: ToggleStyle::default(),
            disabled: false,
            selected: false,
            theme: None,
            on_change: None,
            aria_label: None,
            aria_role: None,
        }
    }

    /// Set checked state
    pub fn checked(mut self, checked: bool) -> Self {
        self.checked = checked;
        self
    }

    /// Set label
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = Some(label.into());
        self
    }

    /// Set size
    pub fn size(mut self, size: ToggleSize) -> Self {
        self.size = size;
        self
    }

    /// Set visual style
    pub fn style(mut self, style: ToggleStyle) -> Self {
        self.style = style;
        self
    }

    /// Set disabled state
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Set selected state (for plugin parameter editing)
    pub fn selected(mut self, selected: bool) -> Self {
        self.selected = selected;
        self
    }

    /// Set theme colors
    pub fn theme(mut self, theme: ToggleTheme) -> Self {
        self.theme = Some(theme);
        self
    }

    /// Set change handler
    pub fn on_change(mut self, handler: impl Fn(bool, &mut Window, &mut App) + 'static) -> Self {
        self.on_change = Some(Box::new(handler));
        self
    }

    /// Set an explicit ARIA label
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Override the default ARIA role (Switch)
    pub fn aria_role(mut self, role: AriaRole) -> Self {
        self.aria_role = Some(role);
        self
    }

    /// Build into element with theme
    pub fn build_with_theme(self, global_theme: &ToggleTheme) -> Stateful<Div> {
        let mut this = self;
        let style = this.style;

        match this.theme.take() {
            Some(ref theme) => match style {
                ToggleStyle::Sliding => this.build_sliding(theme),
                ToggleStyle::Segmented => this.build_segmented(theme),
            },
            None => match style {
                ToggleStyle::Sliding => this.build_sliding(global_theme),
                ToggleStyle::Segmented => this.build_segmented(global_theme),
            },
        }
    }

    fn build_sliding(self, theme: &ToggleTheme) -> Stateful<Div> {
        let track_width = self.size.track_width();
        let track_height = self.size.track_height();
        let knob_size = self.size.knob_size();
        let knob_offset = self.size.knob_offset();
        let checked = self.checked;
        let selected = self.selected;

        let track_bg = if checked {
            theme.checked_bg
        } else {
            theme.unchecked_bg
        };

        let knob_left = if checked {
            track_width - knob_size - knob_offset
        } else {
            knob_offset
        };

        let mut container = div()
            .id(self.id)
            .flex()
            .items_center()
            .gap_2()
            .cursor_pointer();

        // Apply selection styling
        if selected {
            container = container
                .px_3()
                .py_2()
                .rounded_lg()
                .bg(theme.accent_muted)
                .border_l_4()
                .border_color(theme.accent);
        }

        if self.disabled {
            container = container.opacity(0.5).cursor_not_allowed();
        }

        // Track - with border for visibility on dark backgrounds
        let mut track = div()
            .relative()
            .w(track_width)
            .h(track_height)
            .rounded_full()
            .bg(track_bg)
            .border_1()
            .border_color(theme.track_border);

        // Knob - always same color, just moves position
        let knob = div()
            .absolute()
            .top(knob_offset)
            .left(knob_left)
            .w(knob_size)
            .h(knob_size)
            .rounded_full()
            .bg(theme.knob)
            .shadow_md()
            .border_1()
            .border_color(theme.track_border);

        track = track.child(knob);

        // Label first if selected (for row layout)
        if let Some(label) = &self.label
            && selected
        {
            let label_el = match self.size {
                ToggleSize::Sm => div().text_xs(),
                ToggleSize::Md => div().text_sm(),
                ToggleSize::Lg => div(),
            };
            container = container.child(
                label_el
                    .text_color(theme.label)
                    .font_weight(FontWeight::MEDIUM)
                    .child(label.clone()),
            );
        }

        container = container.child(track);

        // Label after track if not selected
        if let Some(label) = &self.label
            && !selected
        {
            let label_el = match self.size {
                ToggleSize::Sm => div().text_xs(),
                ToggleSize::Md => div().text_sm(),
                ToggleSize::Lg => div(),
            };
            container = container.child(label_el.text_color(theme.label).child(label.clone()));
        }

        // Click and keyboard handlers
        if !self.disabled
            && let Some(handler) = self.on_change
        {
            let handler_rc = std::rc::Rc::new(handler);
            let new_checked = !checked;

            // Click handler
            let handler_click = handler_rc.clone();
            container = container.on_mouse_up(MouseButton::Left, move |_event, window, cx| {
                handler_click(new_checked, window, cx);
            });

            // Keyboard handler (Space key when selected)
            if selected {
                let handler_key = handler_rc.clone();
                container = container.on_key_down(move |event, window, cx| {
                    if event.keystroke.key == "space" {
                        handler_key(new_checked, window, cx);
                    }
                });
            }
        }

        container
    }

    fn build_segmented(self, theme: &ToggleTheme) -> Stateful<Div> {
        let checked = self.checked;
        let selected = self.selected;
        let transparent = Rgba {
            r: 0.0,
            g: 0.0,
            b: 0.0,
            a: 0.0,
        };

        let mut container = div().id(self.id).flex().items_center().cursor_pointer();

        // Apply selection styling
        if selected {
            container = container
                .px_3()
                .py_2()
                .rounded_lg()
                .bg(theme.accent_muted)
                .border_l_4()
                .border_color(theme.accent);
        } else {
            container = container.px_3().py_2().rounded_lg();
        }

        if self.disabled {
            container = container.opacity(0.5).cursor_not_allowed();
        }

        // Segmented switch: [OFF | ON]
        let switch = div()
            .flex()
            .rounded_md()
            .border_1()
            .border_color(theme.border)
            .overflow_hidden()
            // OFF button
            .child(
                div()
                    .px_2()
                    .py_1()
                    .text_xs()
                    .font_weight(FontWeight::BOLD)
                    .text_center()
                    .min_w(px(36.0))
                    .border_2()
                    .border_color(if !checked {
                        theme.text_on_accent
                    } else {
                        transparent
                    })
                    .bg(if !checked {
                        theme.accent
                    } else {
                        theme.background
                    })
                    .text_color(if !checked {
                        theme.text_on_accent
                    } else {
                        theme.text_muted
                    })
                    .child("OFF"),
            )
            // Separator
            .child(div().w(px(1.0)).h_full().bg(theme.border))
            // ON button
            .child(
                div()
                    .px_2()
                    .py_1()
                    .text_xs()
                    .font_weight(FontWeight::BOLD)
                    .text_center()
                    .min_w(px(36.0))
                    .border_2()
                    .border_color(if checked {
                        theme.text_on_accent
                    } else {
                        transparent
                    })
                    .bg(if checked {
                        theme.accent
                    } else {
                        theme.background
                    })
                    .text_color(if checked {
                        theme.text_on_accent
                    } else {
                        theme.text_muted
                    })
                    .child("ON"),
            );

        if let Some(label) = self.label.filter(|label| !label.is_empty()) {
            let label_color = if selected {
                theme.text_primary
            } else {
                theme.label
            };
            let label_weight = if selected {
                FontWeight::MEDIUM
            } else {
                FontWeight::NORMAL
            };
            container = container
                .gap_2()
                .child(
                    div()
                        .text_sm()
                        .text_color(label_color)
                        .font_weight(label_weight)
                        .child(label),
                )
                .child(switch);
        } else {
            container = container.child(switch);
        }

        // Click and keyboard handlers
        if !self.disabled
            && let Some(handler) = self.on_change
        {
            let handler_rc = std::rc::Rc::new(handler);
            let new_checked = !checked;

            // Click handler
            let handler_click = handler_rc.clone();
            container = container.on_mouse_up(MouseButton::Left, move |_event, window, cx| {
                handler_click(new_checked, window, cx);
            });

            // Keyboard handler (Space key when selected)
            if selected {
                let handler_key = handler_rc.clone();
                container = container.on_key_down(move |event, window, cx| {
                    if event.keystroke.key == "space" {
                        handler_key(new_checked, window, cx);
                    }
                });
            }
        }

        container
    }
}

impl RenderOnce for Toggle {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        // Register in accessibility tree
        let effective_label = self
            .aria_label
            .clone()
            .or_else(|| self.label.clone())
            .unwrap_or_default();
        cx.register_accessible(AccessibilityNode {
            element_id: self.id.clone(),
            label: effective_label,
            props: AriaProps::with_role(self.aria_role.unwrap_or(AriaRole::Switch))
                .state(AriaState::Checked(self.checked))
                .maybe_state(self.disabled, AriaState::Disabled),
        });

        let global_theme = cx.theme();
        let toggle_theme = ToggleTheme::from(global_theme);
        self.build_with_theme(&toggle_theme)
    }
}

impl IntoElement for Toggle {
    type Element = gpui::Component<Self>;

    fn into_element(self) -> Self::Element {
        gpui::Component::new(self)
    }
}
